  ['lf LiDAR death', '-', '45', '1.00', '1.00*'],
  ['lso LiDAR sparsification', 'mid/high', '45/45', '0.02/0.98', '-(tolerated)/5.0'],
  ['gb† GNSS correlated bias', 'mid/high', '45/45', '1.00/1.00', '3.0/2.3'],
